import { DOCUMENT_KINDS, expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const TAG = "@LIF-04";

type Created = { id: string };

function uniqueVendorName(): string {
  return `LIF04 Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function createVendor(member: APIRequestContext): Promise<string> {
  const response = await member.post("/api/vendors", {
    data: {
      name: uniqueVendorName(),
      category: "services",
      contact_email: `lif04-${Math.random().toString(36).slice(2, 10)}@northwind.test`,
    },
  });
  return (await expectStatus<Created>(response, 201)).id;
}

async function uploadDocument(member: APIRequestContext, vendorId: string, kind: string): Promise<string> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from("%PDF-1.4 lif-04 fixture"),
      },
    },
  });
  return (await expectStatus<Created>(response, 201)).id;
}

async function waitForProcessing(member: APIRequestContext, documentId: string): Promise<void> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const response = await member.get(`/api/documents/${documentId}`);
    const doc = await expectStatus<{ status: string }>(response, 200);
    if (doc.status !== "processing") return;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} still processing after waiting`);
}

function collectStrings(value: unknown, out: string[] = []): string[] {
  if (typeof value === "string") out.push(value);
  else if (Array.isArray(value)) value.forEach((v) => collectStrings(v, out));
  else if (value && typeof value === "object") Object.values(value).forEach((v) => collectStrings(v, out));
  return out;
}

test.describe("resubmitting a vendor with a rejected document", () => {
  test(
    "resubmitting without replacing the rejected w9 is refused with documents_incomplete",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange: a vendor with all three documents, submitted for review.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const vendorId = await createVendor(member);

      const documentIds: string[] = [];
      for (const kind of DOCUMENT_KINDS) {
        documentIds.push(await uploadDocument(member, vendorId, kind));
      }
      for (const documentId of documentIds) {
        await waitForProcessing(member, documentId);
      }

      const firstSubmit = await member.post(`/api/vendors/${vendorId}/submit`);
      await expectStatus(firstSubmit, 200);

      // Arrange: the reviewer rejects the w9 extraction.
      const queueResponse = await reviewer.get("/api/review-queue");
      const queue = await expectStatus<
        Array<{ vendor_id: string; extractions: Array<{ id: string; kind: string }> }>
      >(queueResponse, 200);
      const item = queue.find((entry) => entry.vendor_id === vendorId);
      expect(item, "vendor should appear in the review queue").toBeTruthy();
      const w9 = item!.extractions.find((extraction) => extraction.kind === "w9");
      expect(w9, "a w9 extraction should exist for review").toBeTruthy();

      const decisionResponse = await reviewer.post(`/api/extractions/${w9!.id}/decision`, {
        data: { decision: "reject", note: "W-9 is illegible" },
      });
      await expectStatus(decisionResponse, 200);

      // Act: the member resubmits without replacing the w9.
      const resubmit = await member.post(`/api/vendors/${vendorId}/submit`);

      // Assert: refused with the documented error code and only w9 missing.
      const body = await expectStatus<{ error: { code: string } }>(resubmit, 409);
      expect(body.error.code).toBe("documents_incomplete");

      const strings = collectStrings(body.error);
      expect(strings).toContain("w9");
      for (const kind of DOCUMENT_KINDS.filter((k) => k !== "w9")) {
        expect(strings, `"${kind}" must not be listed as missing`).not.toContain(kind);
      }
    },
  );
});
